let raw =
  $json.output ||
  $json.text ||
  $json.response ||
  $json.message ||
  '';

if (typeof raw !== 'string') {
  raw = JSON.stringify(raw, null, 2);
}

raw = raw.trim();

if (
  (raw.startsWith('"') && raw.endsWith('"')) ||
  (raw.startsWith("'") && raw.endsWith("'"))
) {
  raw = raw.slice(1, -1);
}

const cleanOutput = raw
  .replace(/\\n/g, '\n')
  .replace(/\\r/g, '')
  .replace(/\\t/g, ' ')
  .replace(/\\"/g, '"')
  .replace(/[ \t]+$/gm, '')
  .trim();

function extractField(text, fieldName, nextFieldName) {
  const start = text.indexOf(fieldName + ':');
  if (start === -1) return '';

  const valueStart = start + fieldName.length + 1;
  let valueEnd = text.length;

  if (nextFieldName) {
    const nextStart = text.indexOf(nextFieldName + ':', valueStart);
    if (nextStart !== -1) {
      valueEnd = nextStart;
    }
  }

  return text.slice(valueStart, valueEnd).trim();
}

const ticketTitle = extractField(cleanOutput, 'Ticket Title', 'Summary');
const summary = extractField(cleanOutput, 'Summary', 'Category');
const category = extractField(cleanOutput, 'Category', 'Priority');
const priority = extractField(cleanOutput, 'Priority', 'Security Risk');
const securityRisk = extractField(cleanOutput, 'Security Risk', 'Business Impact');
const businessImpact = extractField(cleanOutput, 'Business Impact', 'Recommended Actions');
const recommendedActions = extractField(cleanOutput, 'Recommended Actions', 'Suggested User Response');
const suggestedUserResponse = extractField(cleanOutput, 'Suggested User Response', 'Internal Technical Note');
const internalTechnicalNote = extractField(cleanOutput, 'Internal Technical Note', 'Needs Human Review');
const needsHumanReview = extractField(cleanOutput, 'Needs Human Review', null);

const now = new Date();
const timestamp = now.toISOString();

const pad = (n) => String(n).padStart(2, '0');

const ticketId =
  'TRIAGE-' +
  now.getUTCFullYear() +
  pad(now.getUTCMonth() + 1) +
  pad(now.getUTCDate()) +
  '-' +
  pad(now.getUTCHours()) +
  pad(now.getUTCMinutes()) +
  pad(now.getUTCSeconds());

function getSlaTarget(priorityValue) {
  const value = String(priorityValue).toLowerCase();

  if (value.includes('critical')) return '1 hour';
  if (value.includes('high')) return '4 hours';
  if (value.includes('medium')) return '1 business day';
  if (value.includes('low')) return '3 business days';

  return 'To be defined';
}

function getAssignedQueue(categoryValue) {
  const value = String(categoryValue).toLowerCase();

  if (
    value.includes('microsoft 365') ||
    value.includes('exchange') ||
    value.includes('teams')
  ) {
    return 'Microsoft 365 Support';
  }

  if (
    value.includes('entra') ||
    value.includes('azure ad') ||
    value.includes('password') ||
    value.includes('mfa') ||
    value.includes('access')
  ) {
    return 'Identity & Access Support';
  }

  if (value.includes('aws') || value.includes('iam')) {
    return 'Cloud IAM Support';
  }

  if (value.includes('security') || value.includes('phishing')) {
    return 'Security Operations';
  }

  if (value.includes('network') || value.includes('vpn')) {
    return 'Network Support';
  }

  if (value.includes('device') || value.includes('hardware')) {
    return 'Field Support';
  }

  if (value.includes('software') || value.includes('application')) {
    return 'Application Support';
  }

  return 'General IT Support';
}

function shouldEscalate(priorityValue, riskValue, reviewValue) {
  const priorityText = String(priorityValue).toLowerCase();
  const riskText = String(riskValue).toLowerCase();
  const reviewText = String(reviewValue).toLowerCase();

  if (priorityText.includes('critical') || priorityText.includes('high')) {
    return 'Yes';
  }

  if (riskText.includes('high') || riskText.includes('medium')) {
    return 'Yes';
  }

  if (reviewText.includes('yes')) {
    return 'Yes';
  }

  return 'No';
}

const slaTarget = getSlaTarget(priority);
const assignedQueue = getAssignedQueue(category);
const escalationRequired = shouldEscalate(priority, securityRisk, needsHumanReview);

return [
  {
    json: {
      timestamp: timestamp,
      ticket_id: ticketId,
      ticket_title: ticketTitle,
      summary: summary,
      category: category,
      priority: priority,
      security_risk: securityRisk,
      business_impact: businessImpact,
      recommended_actions: recommendedActions,
      suggested_user_response: suggestedUserResponse,
      internal_technical_note: internalTechnicalNote,
      needs_human_review: needsHumanReview,
      status: 'New',
      sla_target: slaTarget,
      assigned_queue: assignedQueue,
      escalation_required: escalationRequired,
      clean_output: cleanOutput,
      output: cleanOutput
    }
  }
];
